const express = require('express');
const crypto = require('crypto');
const vm = require('vm');

const app = express();
app.use(express.json());

// Cross-service shared secret for HMAC verification
const SERVICE_SECRET = process.env.SERVICE_SECRET || crypto.randomBytes(32).toString('hex');
const ALLOWED_SERVICES = ['billing-svc', 'inventory-svc', 'analytics-svc'];

// Rate limiting state
const requestCounts = new Map();

function resetRateLimits() {
  requestCounts.clear();
}
setInterval(resetRateLimits, 60000);

// Verify cross-service HMAC token
function verifyServiceToken(token, serviceId, timestamp, body) {
  const payload = `${serviceId}:${timestamp}:${JSON.stringify(body)}`;
  const expected = crypto.createHmac('sha256', SERVICE_SECRET)
    .update(payload)
    .digest('hex');
  return crypto.timingSafeEqual(
    Buffer.from(token, 'hex'),
    Buffer.from(expected, 'hex')
  );
}

// Authentication middleware
function authenticateService(req, res, next) {
  const serviceId = req.headers['x-service-id'];
  const token = req.headers['x-service-token'];
  const timestamp = req.headers['x-timestamp'];

  if (!serviceId || !token || !timestamp) {
    return res.status(401).json({ error: 'Missing authentication headers' });
  }

  if (!ALLOWED_SERVICES.includes(serviceId)) {
    return res.status(403).json({ error: 'Unknown service' });
  }

  const now = Date.now();
  const reqTime = parseInt(timestamp, 10);
  if (Math.abs(now - reqTime) > 30000) {
    return res.status(401).json({ error: 'Token expired' });
  }

  try {
    if (!verifyServiceToken(token, serviceId, timestamp, req.body)) {
      return res.status(401).json({ error: 'Invalid token' });
    }
  } catch (e) {
    return res.status(401).json({ error: 'Token verification failed' });
  }

  // Rate limiting per service
  const count = requestCounts.get(serviceId) || 0;
  if (count > 100) {
    return res.status(429).json({ error: 'Rate limit exceeded' });
  }
  requestCounts.set(serviceId, count + 1);

  req.serviceId = serviceId;
  next();
}

// Transform engine for data pipeline operations
class TransformEngine {
  constructor() {
    this.transforms = new Map();
    this.sandboxContext = {
      Math: Math,
      parseInt: parseInt,
      parseFloat: parseFloat,
      String: String,
      Number: Number,
      Boolean: Boolean,
      Array: Array,
      Object: Object,
      JSON: JSON,
      Date: Date
    };
  }

  registerTransform(name, spec) {
    if (typeof spec.expression !== 'string') {
      throw new Error('Transform expression must be a string');
    }
    if (spec.expression.length > 500) {
      throw new Error('Expression too long');
    }
    this.transforms.set(name, spec);
  }

  executeTransform(name, data) {
    const spec = this.transforms.get(name);
    if (!spec) throw new Error(`Transform '${name}' not found`);

    const context = vm.createContext({
      ...this.sandboxContext,
      data: data,
      result: null
    });

    const script = new vm.Script(`result = (function(data) { return ${spec.expression}; })(data);`, {
      timeout: 1000,
      filename: `transform_${name}.js`
    });

    script.runInContext(context);
    return context.result;
  }

  // Chain multiple transforms with intermediate validation
  executeChain(chain, initialData) {
    let current = initialData;
    for (const step of chain) {
      current = this.executeTransform(step, current);
      if (current === undefined || current === null) {
        throw new Error(`Transform '${step}' returned null/undefined`);
      }
    }
    return current;
  }
}

const engine = new TransformEngine();

// Register a new transform
app.post('/api/transforms', authenticateService, (req, res) => {
  const { name, expression, description } = req.body;

  if (!name || !expression) {
    return res.status(400).json({ error: 'Name and expression required' });
  }

  if (!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(name)) {
    return res.status(400).json({ error: 'Invalid transform name' });
  }

  try {
    engine.registerTransform(name, { expression, description, owner: req.serviceId });
    res.json({ success: true, name });
  } catch (e) {
    res.status(400).json({ error: e.message });
  }
});

// Execute a transform or chain
app.post('/api/execute', authenticateService, (req, res) => {
  const { transform, chain, data } = req.body;

  try {
    let result;
    if (chain && Array.isArray(chain)) {
      result = engine.executeChain(chain, data);
    } else if (transform) {
      result = engine.executeTransform(transform, data);
    } else {
      return res.status(400).json({ error: 'Specify transform or chain' });
    }
    res.json({ result });
  } catch (e) {
    res.status(500).json({ error: e.message });
  }
});

// Health check (no auth required)
app.get('/health', (req, res) => {
  res.json({ status: 'ok', uptime: process.uptime() });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, '127.0.0.1', () => {
  console.log(`Transform service listening on port ${PORT}`);
});

module.exports = app;
